#!/usr/bin/env node
/**
 * 从现有根目录 .env.* 反灌 env/manifest.json 与 env/values/<profile>.json
 */
import fs from "node:fs";
import path from "node:path";
import {
  REPO_ROOT,
  parseEnvFile,
  writeJson,
} from "./lib.mjs";

const PROFILE_TARGETS = {
  local: [".env.api.local", ".env.web.local", ".env.web.cloudflare"],
  production: [
    ".env.api.production",
    ".env.web.production",
    ".env.trigger.production",
    ".env.web.cloudflare.production",
  ],
};

function stripGeneratedHeader(content) {
  return content.replace(/^# GENERATED BY pnpm env:sync[^\n]*\n/, "");
}

function importProfile(profile, existingManifest) {
  const targets = {};
  const parsedByTarget = {};

  for (const relativePath of PROFILE_TARGETS[profile]) {
    const absolutePath = path.join(REPO_ROOT, relativePath);
    if (!fs.existsSync(absolutePath)) {
      console.warn(`[skip] ${relativePath} not found`);
      continue;
    }
    const raw = stripGeneratedHeader(fs.readFileSync(absolutePath, "utf8"));
    const parsed = parseEnvFile(raw);
    parsedByTarget[relativePath] = parsed;
    targets[relativePath] = {
      keys: parsed.order,
      overrides: {},
    };
  }

  const allKeys = new Set();
  for (const parsed of Object.values(parsedByTarget)) {
    for (const key of parsed.order) {
      allKeys.add(key);
    }
  }

  const values = {};

  for (const key of allKeys) {
    const perTarget = {};
    for (const [targetPath, parsed] of Object.entries(parsedByTarget)) {
      if (Object.prototype.hasOwnProperty.call(parsed.entries, key)) {
        perTarget[targetPath] = parsed.entries[key];
      }
    }
    const distinct = [...new Set(Object.values(perTarget))];
    if (distinct.length === 1) {
      values[key] = distinct[0];
      continue;
    }
    for (const [targetPath, targetValue] of Object.entries(perTarget)) {
      targets[targetPath].overrides[key] = targetValue;
    }
  }

  for (const targetConfig of Object.values(targets)) {
    if (Object.keys(targetConfig.overrides).length === 0) {
      delete targetConfig.overrides;
    }
  }

  existingManifest.profiles[profile] = { targets };
  const valuesPath = path.join(REPO_ROOT, "env", "values", `${profile}.json`);
  writeJson(valuesPath, { values });
  console.log(`Imported profile "${profile}" -> env/values/${profile}.json`);
}

function main() {
  const manifestPath = path.join(REPO_ROOT, "env", "manifest.json");
  const manifest = fs.existsSync(manifestPath)
    ? JSON.parse(fs.readFileSync(manifestPath, "utf8"))
    : { profiles: {} };

  if (!manifest.profiles) {
    manifest.profiles = {};
  }

  for (const profile of Object.keys(PROFILE_TARGETS)) {
    importProfile(profile, manifest);
  }

  writeJson(manifestPath, manifest);
  console.log(`Wrote ${manifestPath}`);
  console.log("Run pnpm env:sync --dry-run to verify before overwriting .env files.");
}

main();
